sections.body:
- `dev:{user_id}` → list of {token, platform, created_at}
- `tpl:{template_id}` → template body + variable schema
- `set:{user_id}` → opt-in matrix per channel, quiet-hours, locale

steps.codeOrCommand:
POST /v1/notify HTTP/1.1
Host: notify.internal
Authorization: Bearer <svc-token>
Idempotency-Key: ord-9921-shipped
Content-Type: application/json { "user_id": 4782, "channel": "push", "template_id": "order_shipped_v3", "variables": {"order_id": 9921, "eta": "Friday"}
}

if dedupe_store.seen('ord-9921-shipped'): return 200 (noop)
tmpl = cache.get('tpl:order_shipped_v3') or db.get_template(...)
assert tmpl.binds(variables)

MGET tpl:order_shipped_v3 dev:4782 set:4782
# tpl: { body: 'Your order #{{order_id}} ships {{eta}}', vars: [order_id, eta] }
# dev: [{token:'aXb...', platform:'apns'}, {token:'cYd...', platform:'apns'}]
# set: { push:true, email:true, sms:true, quiet_start:23, quiet_end:7 }

nid = uuid7
kafka.produce( topic='notif.push', key=str(4782), value={ 'nid': nid, 'user_id': 4782, 'template_id': 'order_shipped_v3', 'variables': {'order_id':9921,'eta':'Friday'}, 'created_at': now, 'idempotency_key': 'ord-9921-shipped' }
)

POST /v1/notify/broadcast
{ "segment_id": "seg_spring_promo_2026", "estimated_recipients": 100000000, "template_id": "spring_promo_v1", "channel": "push", "send_window": {"start": "2026-04-24T17:00:00Z", "end": "2026-04-24T17:10:00Z"}
}

bid = uuid7
kafka.produce('broadcast.jobs', key=bid, value={'segment_id': seg, 'template_id': tmpl,...})
return 202, {'broadcast_id': bid, 'status': 'scheduled'}

# in fanout worker
for batch in segment_store.iter_chunks(seg_id, size=10_000): records = [(u, template_id, vars) for u in batch] kafka.produce_batch('notif.push', records)
# ~10K batches × 10K records = 100M

# HPA rule
if kafka_consumer_lag > 5_000_000: desired_replicas = min(current * 1.5, 500)
# workers in parallel across 200 partitions

# Cassandra LOCAL_QUORUM writes, per-worker batched
BATCH INSERT INTO notif_attempts (...) VALUES (...); INSERT INTO notif_attempts (...) VALUES (...);... -- 50 per batch
APPLY BATCH;
